      summary.getPaymentAdjustment(),
      summary.getFinalTotal(),
      summary.getInstallments(),
      summary.getInstallmentAmount(),
      summary.getNextPurchaseCredit(),
      summary.isGift()
    );

    return new OrderResponse(
      order.getId(),
      order.getStatus().name(),
      order.getCreatedAt(),
      summaryResponse,
      items,
      order.getTrackingCode()
    );
  }

