    );

    OrderSummary summary = pricingService.calculateSummary(
      items,
      "WELCOME10",
      ShippingMethod.STORE_PICKUP,
      BigDecimal.ZERO,
      1,
      Region.SOUTHEAST,
      PaymentMethod.PIX,
      1,
      ClubTier.BRONZE,
      true
    );

    assertTrue(summary.getCouponDiscount().compareTo(BigDecimal.ZERO) > 0);
  }

  @Test
