      ShippingMethod.EXPRESS,
      new BigDecimal("50.00"),
      3,
      Region.SOUTHEAST,
      PaymentMethod.PIX,
      1,
      ClubTier.GOLD,
      false
    );

    assertEquals(new BigDecimal("0.00"), summary.getShippingCost());
    assertTrue(summary.getNextPurchaseCredit().compareTo(BigDecimal.ZERO) > 0);
    assertTrue(summary.isGift());
  }
}

